function setup()
    local ok, err = Launch("core/os.prg")
    if not ok then
        print("boot: cannot start core/os.prg: " .. tostring(err) .. " trying .lua file")
        ok, err = Launch("core/os.lua")
        if not ok then
            print("boot: cannot start core/os.lua: " .. tostring(err))
        end
    end
end

function tick()
    ExitProgram()
end

